<script setup>
import {ref} from 'vue'
import {voiceApi} from '../voice/operations'
const props=defineProps({call:Object,codes:Array});const emit=defineEmits(['saved','cancel'])
const code=ref(props.call.disposition_code||''),notes=ref(props.call.disposition_notes||''),callback=ref(''),reason=ref(''),busy=ref(false),error=ref('');let key=null,lastBody=null
async function save(){busy.value=true;error.value='';try{const d={revision:props.call.disposition_revision,code:code.value,notes:notes.value||null,callback_at:code.value==='callback'&&callback.value?new Date(callback.value).toISOString():null,correction_reason:reason.value||null};const serialized=JSON.stringify(d);if(serialized!==lastBody){key=crypto.randomUUID();lastBody=serialized}await voiceApi('/operations/calls/'+props.call.id+'/disposition','POST',{...d,idempotency_key:key});emit('saved')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><form @submit.prevent="save" class="disposition-form"><h3>Tabular chamada</h3><p>{{call.destination}} · A tabulação não altera o resultado informado pela telefonia.</p><div v-if="error" role="alert" class="error">{{error}}</div><label>Resultado da conversa<select aria-label="Resultado da conversa" v-model="code" required><option value="">Selecione</option><option v-for="c in codes.filter(c=>c.active)" :key="c.code" :value="c.code">{{c.label}}</option></select></label><label>Observações<textarea v-model="notes" maxlength="2000" :required="codes.find(c=>c.code===code)?.notes_required"/></label><label v-if="code==='callback'">Retorno solicitado<input v-model="callback" type="datetime-local" required><small>Registra o pedido para acompanhamento. Não reinicia a jornada nem agenda uma ligação automática.</small></label><label v-if="call.disposition_revision">Motivo da correção<textarea v-model="reason" required minlength="8" maxlength="500"/></label><button class="primary" :disabled="busy">Salvar tabulação</button> <button type="button" class="secondary" @click="emit('cancel')">Fechar</button></form></template>
